// Generate renderer symbols and CSS images directly from the approved masters.
// node design/icons/build-web.mjs [--check]
// Website symbols are generated by cloudflare/site-chrome.mjs from web-symbols.mjs.
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { root } from './svg-tools.mjs';
import { masterSvg, symbol } from './web-symbols.mjs';

const check = process.argv.includes('--check');
const read = file => fs.readFileSync(path.join(root, file), 'utf8').replace(/\r/g, '');
const htmlPath = 'src/renderer/index.html';
const html = read(htmlPath);
const source = html + read('src/renderer/app.js') + read('src/renderer/motion/topbar.js');
// References outside the generated block define the subset shipped in the renderer.
const start = '<!-- Playful icons: generated by design/icons/build-web.mjs -->';
const end = '<!-- End Playful icons -->';
const block = new RegExp(start + '[\\s\\S]*?' + end);
assert(block.test(html), 'Missing renderer icon markers');
const references = source.replace(block, '');
const ids = [...new Set([...references.matchAll(/#owc-([a-z-]+)/g)].map(m => m[1]))].sort();
assert(ids.length > 0, 'No renderer icon references');
const sprite = start + '\n<svg width="0" height="0" aria-hidden="true" focusable="false" class="icon-sprite">\n' +
  ids.map(id => '  ' + symbol(id, 'owc-' + id)).join('\n') + '\n</svg>\n' + end;
const uri = (id, ink) => 'url("data:image/svg+xml,' + encodeURIComponent(masterSvg(id).replaceAll('currentColor', ink).trim()).replaceAll("'", '%27') + '")';
const css = '/* Generated by design/icons/build-web.mjs. Do not edit. */\n:root {\n' +
  '  --owc-add: ' + uri('add', 'currentColor') + ';\n' +
  // Existing select foregrounds are retained: CSS image documents cannot inherit currentColor.
  '  --owc-chevron-light: ' + uri('chevron-down', '#5c6778') + ';\n' +
  '  --owc-chevron-dark: ' + uri('chevron-down', '#b9c3d3') + ';\n}\n';
const outputs = { [htmlPath]: html.replace(block, sprite), 'src/renderer/icons.css': css };
let failures = 0;
for (const [file, expected] of Object.entries(outputs)) {
  if (check) {
    if (!fs.existsSync(path.join(root, file)) || read(file) !== expected) { console.error('Out of date: ' + file); failures++; }
  } else fs.writeFileSync(path.join(root, file), expected);
}
assert.equal(failures, 0, 'Run node design/icons/build-web.mjs');
console.log('Playful web icons: ' + ids.length + ' renderer symbols and CSS images ' + (check ? 'match' : 'generated') + '.');
